(() => {
  const canvas=document.getElementById('portrait'),ctx=canvas.getContext('2d');
  const image=new Image();
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const mobile=matchMedia('(max-width:700px)');
  const eyes=[
    {cx:695,cy:467,dx:23,dy:13,path:'M 652 478 C 647 455 660 433 682 430 C 714 424 741 454 739 503 C 715 504 673 491 652 478 Z'},
    {cx:895,cy:517,dx:27,dy:12,path:'M 841 533 C 842 507 861 481 886 481 C 918 480 944 503 949 537 C 945 563 884 553 841 533 Z'}
  ];
  let target={x:0,y:0},gaze={x:0,y:0},frame=null,ready=false;
  function render(){
    frame=null;
    gaze.x+=(target.x-gaze.x)*.18;gaze.y+=(target.y-gaze.y)*.18;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.save();
    if(mobile.matches){ctx.translate(-365,80-155);}
    ctx.drawImage(image,0,0);
    if(!reduced.matches)for(const eye of eyes){
      ctx.save();ctx.clip(new Path2D(eye.path));
      const white=ctx.createRadialGradient(eye.cx+7,eye.cy-9,5,eye.cx,eye.cy,66);
      white.addColorStop(0,'#fffaf8');white.addColorStop(.65,'#f7e9e5');white.addColorStop(1,'#c99f98');
      ctx.fillStyle=white;ctx.fillRect(eye.cx-75,eye.cy-65,150,130);
      const x=eye.cx+gaze.x*eye.dx,y=eye.cy+gaze.y*eye.dy;
      ctx.save();ctx.beginPath();ctx.ellipse(x,y,23,29,-.10,0,Math.PI*2);ctx.clip();
      // Original iris texture moves as one rigid piece. Eyelids and skin never deform.
      ctx.drawImage(image,652,439,46,58,x-23,y-29,46,58);
      ctx.restore();
      // A fixed soft upper-lid shadow keeps the eye seated in the face.
      const shadow=ctx.createLinearGradient(0,eye.cy-38,0,eye.cy+20);
      shadow.addColorStop(0,'rgba(76,40,34,.26)');shadow.addColorStop(.55,'rgba(76,40,34,0)');
      ctx.fillStyle=shadow;ctx.fillRect(eye.cx-75,eye.cy-65,150,130);
      ctx.restore();
    }
    ctx.restore();
    if(Math.abs(target.x-gaze.x)+Math.abs(target.y-gaze.y)>.002)frame=requestAnimationFrame(render);
  }
  function update(event){
    if(!ready||reduced.matches)return;
    const rect=canvas.getBoundingClientRect();
    let x,y;
    if(mobile.matches){x=(event.clientX-rect.left)/rect.width*941+365;y=(event.clientY-rect.top)/rect.height*941+75;}
    else{const scale=Math.min(rect.width/image.width,rect.height/image.height);x=(event.clientX-rect.left-(rect.width-image.width*scale)/2)/scale;y=(event.clientY-rect.top-(rect.height-image.height*scale)/2)/scale;}
    // One shared target prevents crossed eyes; ±1 spans the usable eye opening.
    target={x:Math.max(-1,Math.min(1,(x-790)/380)),y:Math.max(-1,Math.min(1,(y-495)/270))};
    if(!frame)frame=requestAnimationFrame(render);
  }
  function resize(){if(!ready)return;canvas.width=mobile.matches?941:image.width;canvas.height=mobile.matches?941:image.height;if(frame)cancelAnimationFrame(frame);render();}
  image.onload=()=>{ready=true;resize();};
  image.src='data:image/png;base64,';
  window.addEventListener('pointermove',update,{passive:true});
  document.addEventListener('pointerleave',()=>{target={x:0,y:0};if(ready&&!frame)frame=requestAnimationFrame(render);});
  window.addEventListener('resize',resize);reduced.addEventListener('change',resize);
})();

// Same per-character bounce used in the original portfolio list.
const nameHeading = document.getElementById('name');
const letters = [];
Array.from(nameHeading.textContent).forEach((char) => {
  const span = document.createElement('span');
  span.className = 'bouncy-char';
  span.textContent = char === ' ' ? '\u00A0' : char;
  letters.push(span);
});
nameHeading.replaceChildren(...letters);
function bounceLetter(letter) {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  letter.classList.remove('is-bouncing');
  void letter.offsetWidth;
  letter.classList.add('is-bouncing');
  letter.addEventListener('animationend', () => letter.classList.remove('is-bouncing'), {once:true});
}
letters.forEach(letter => letter.addEventListener('mouseenter', () => bounceLetter(letter)));
function bounceName() { letters.forEach((letter, i) => setTimeout(() => bounceLetter(letter), i * 30)); }
nameHeading.addEventListener('mouseenter', bounceName);
nameHeading.addEventListener('focus', bounceName);
